          const a = gOsc(g, "sine", 42, throb, 0.3), b = gOsc(g, "sine", 42.7, throb, 0.25);
          const c = gOsc(g, "triangle", 84, throb, 0.12), d = gOsc(g, "sawtooth", 63, throb, 0.05);
