          const list = this.list(this.biome);
          const caught = list.filter((s) => this.known(s.id) === "caught").length;
          const pct = Math.round(caught / list.length * 100);
          drawText(ctx2, B2.name, x + 12, y + 10, { scale: 2, color: INK2 });
